// ==== CLIENTI: un token diverso per ogni cliente ====
// Il token deve essere uguale a "segnalazioni_token" nel secrets.yaml del cliente
const CLIENTI = {
  // Genera ogni token con:  openssl rand -hex 24
  'TOKEN-CLIENTE-1': 'Cliente Esempio',
  // 'TOKEN-CLIENTE-2': 'Famiglia Rossi',
};

const req = $input.first().json;
const headers = req.headers || {};
const token = headers['x-segnalazioni-token'] || '';
const cliente = CLIENTI[token] || null;
const azione = String(req.webhookUrl || '').includes('segnalazioni-stato') ? 'stato' : 'invio';

return [{ json: { ok: !!cliente, cliente, azione, ...(req.body || {}) } }];

