// ID del progetto "Segnalazioni clienti" in Vikunja
const PROGETTO = ID_PROGETTO; // <-- metti il numero, es. 2
const MAX_RISOLTE = 15;

const cliente = $('Verifica cliente').first().json.cliente;
const prefisso = `[${cliente}]`;

const dec = s => String(s || '')
  .replace(/<br\s*\/?>/gi, '\n')
  .replace(/<\/p>\s*<p>/gi, '\n')
  .replace(/<[^>]+>/g, '')
  .replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&quot;/g, '"').replace(/&#39;/g, "'").replace(/&amp;/g, '&')
  .trim();
const campo = (html, nome) => {
  const m = String(html || '').match(new RegExp(`<b>${nome}:</b>\\s*([^<]*)`));
  return m ? dec(m[1]) : '';
};
const dataIt = iso => {
  const d = new Date(iso);
  if (isNaN(d)) return '';
  return d.toLocaleString('it-IT', { timeZone: 'Europe/Rome', day: '2-digit', month: '2-digit', year: 'numeric', hour: '2-digit', minute: '2-digit' });
};

const tasks = $input.all().map(i => i.json)
  .filter(t => t && t.id && t.project_id === PROGETTO && String(t.title || '').startsWith(prefisso));

const richieste = tasks.map(t => {
  const desc = String(t.description || '');
  const inLavorazione = (t.labels || []).some(l => String(l.title || '').trim().toLowerCase() === 'in lavorazione');
  const stato = t.done ? 'risolta' : (inLavorazione ? 'in_lavorazione' : 'inviata');
  const parti = desc.split('<b>Testo:</b></p>');
  return {
    id: t.id,
    stato,
    tipo: campo(desc, 'Tipo') || '',
    stanza: campo(desc, 'Stanza/dispositivo') || '-',
    data: campo(desc, 'Inviata il') || dataIt(t.created),
    risolta_il: t.done ? dataIt(t.done_at) : '',
    testo: dec(parti.length > 1 ? parti[1] : desc),
    _ordine: t.done ? new Date(t.done_at).getTime() : t.id,
  };
});

const aperte = richieste.filter(r => r.stato !== 'risolta').sort((a, b) => b.id - a.id);
const risolte = richieste.filter(r => r.stato === 'risolta').sort((a, b) => b._ordine - a._ordine).slice(0, MAX_RISOLTE);
const lista = [...aperte, ...risolte].map(({ _ordine, ...r }) => r);

return [{ json: {
  aggiornato: new Date().toISOString(),
  aperte: aperte.length,
  inviate: aperte.filter(r => r.stato === 'inviata').length,
  in_lavorazione: aperte.filter(r => r.stato === 'in_lavorazione').length,
  risolte: richieste.filter(r => r.stato === 'risolta').length,
  richieste: lista,
} }];
